package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;
import com.petlis.common.security.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.PlatformTransactionManager;
import org.apache.pdfbox.pdmodel.*;
import java.math.BigDecimal;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
@SpringBootTest @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyReportMailLocalDatabaseTest {
 @Autowired FeatureStore store;@Autowired PlatformTransactionManager manager;
 AccessService access;LegacyReportMailService service;LegacyMailTransport transport;LegacyMailTransportTest.Sink sink;
 String prefix;int actor;long order,hospital,contact,detail,profile;Path root,pdf;Map<String,String> old=new HashMap<>();
 String key(){return "report_"+UUID.randomUUID().toString().replace("-","");}
 void gate(String name,String value){if(!old.containsKey(name)){var rows=store.jdbc().queryForList("SELECT config_value FROM lin_operational_config WHERE config_key=? AND scope_type='GLOBAL' AND scope_id=0",name);old.put(name,rows.isEmpty()?null:rows.get(0).get("config_value").toString());}store.jdbc().update("INSERT INTO lin_operational_config(config_key,config_value,description,updated_by) VALUES(?,?,'synthetic report mail fixture',?) ON DUPLICATE KEY UPDATE config_value=VALUES(config_value)",name,value,actor);}
 @BeforeEach void setup()throws Exception{
  assertTrue(System.getenv("DB_URL").startsWith("jdbc:mysql://127.0.0.1:13306/laboklin?"));prefix="it_report_"+UUID.randomUUID().toString().substring(0,8);actor=(int)store.insert("INSERT INTO lin_user(username,nickname,status) VALUES(?,'报告邮件测试','normal')",prefix);hospital=store.insert("INSERT INTO lin_lb_infohospital(HospitalName,HospitalName_en,PayType,amount) VALUES(?,?,0,20)",prefix,prefix);order=LegacyDetailFixtures.order(store,prefix,actor);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET InfoHospitalId=?,AnimalName=?,SampleStatus=2 WHERE ListDiagnosisProjectId=?",hospital,prefix,order);
  contact=store.insert("INSERT INTO lin_lb_infohospitalcontact(InfoHospitalId,isFinanceContact,Name,Tel,Mail,Fax,ContactRemark,CreateDt) VALUES(?,0,?,'','doctor@example.test','','',NOW())",hospital,prefix);
  access=mock(AccessService.class);when(access.current()).thenReturn(new CurrentActor(actor,Set.of(PlatformRole.ADMIN),Set.of(),Set.of(),new DataScope(true,Set.of(),Set.of(),null)));var renderer=new LegacyOrderDetailService(store,access,new LegacyReportLinks("https://petlis.invalid/","synthetic-report-test-key"));
  gate("legacy-order-details","{\"enabled\":true,\"writeEnabled\":true}");detail=renderer.create(order,new LegacyOrderDetailService.CreateCommand(246,new BigDecimal("12.50"),"10",new BigDecimal("12.50"),prefix,0,"原报告邮件",0,0,0,0,"<p>原邮件正文</p>","<p>原报告正文</p>",key()));
  gate("legacy-report-mail","{\"enabled\":true,\"writeEnabled\":true,\"sendEnabled\":true,\"reconcileEnabled\":true}");
  profile=store.jdbc().queryForObject("SELECT COALESCE(MAX(DictMailServerId),0)+1 FROM lin_lb_dictmailserver",Long.class);store.jdbc().update("INSERT INTO lin_lb_dictmailserver VALUES(?,'synthetic-report.invalid',587,'sender@laboklin.cn','synthetic-only','copy@example.test')",profile);
  var parent=Path.of(System.getProperty("user.home"),".local/share/petlis/reports");Files.createDirectories(parent);root=Files.createTempDirectory(parent,"it-report-mail-");pdf=root.resolve(order+"_"+detail+"/existing.pdf");Files.createDirectories(pdf.getParent());try(var document=new PDDocument()){document.addPage(new PDPage());document.save(pdf.toFile());}
  sink=new LegacyMailTransportTest.Sink();transport=spy(new LegacyMailTransport("TEST_LOCAL",sink.port(),false));service=new LegacyReportMailService(store,access,renderer,transport,manager,(int)profile,"","synthetic-report-signing-key",new LegacyReportFiles(root.toString()));
 }
 @AfterEach void cleanup()throws Exception{if(sink!=null)sink.close();if(actor==0)return;store.jdbc().update("DELETE a FROM lin_mail_attempt a JOIN lin_mail_message m ON m.id=a.message_id WHERE m.requested_by=? AND m.business_type='REPORT_MAIL'",actor);store.jdbc().update("DELETE FROM lin_mail_message WHERE requested_by=? AND business_type='REPORT_MAIL'",actor);store.jdbc().update("DELETE FROM lin_audit_record WHERE actor_user_id=? AND resource_type IN ('LEGACY_REPORT_MAIL','LEGACY_ORDER_DETAIL')",actor);for(var entry:old.entrySet())if(entry.getValue()==null)store.jdbc().update("DELETE FROM lin_operational_config WHERE config_key=? AND description='synthetic report mail fixture'",entry.getKey());else store.jdbc().update("UPDATE lin_operational_config SET config_value=? WHERE config_key=? AND scope_type='GLOBAL' AND scope_id=0",entry.getValue(),entry.getKey());store.jdbc().update("DELETE FROM lin_lb_dictmailserver WHERE DictMailServerId=? AND ServerHost='synthetic-report.invalid'",profile);if(detail>0)store.jdbc().update("DELETE FROM lin_lb_diagnosisdetail_info WHERE diagnosisdetail_id=?",detail);store.jdbc().update("DELETE FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=? AND ListDiagnosisProjectId=?",detail,order);store.jdbc().update("DELETE FROM lin_lb_notification WHERE order_id=? AND animal_name=?",order,prefix);store.jdbc().update("DELETE FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=? AND UserNO=?",order,prefix);if(contact>0)store.jdbc().update("DELETE FROM lin_lb_infohospitalcontact WHERE InfoHospitalContactId=? AND InfoHospitalId=?",contact,hospital);store.jdbc().update("DELETE FROM lin_lb_infohospital WHERE InfoHospitalId=? AND HospitalName=?",hospital,prefix);store.jdbc().update("DELETE FROM lin_user WHERE id=? AND username=?",actor,prefix);if(root!=null)try(var paths=Files.walk(root)){for(var p:paths.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
 LegacyReportMailService.Command command(){return new LegacyReportMailService.Command(contact,"报告发送", "<p>修订后的发送正文</p>",key(),service.draft(detail,0).get("editToken").toString(),"existing.pdf");}
 @Test void reportSendsWithoutAttachmentAndUpdatesOnlyOriginalSendFlags()throws Exception{
  var original=store.one("SELECT MailReport,ReportResult FROM lin_lb_diagnosisdetail_info WHERE diagnosisdetail_id=?",detail);var before=store.one("SELECT TestPrice,OrginalPrice,OrginalDiscount,PDFHttpUrl FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",detail);
  assertEquals("<p>原邮件正文</p>",service.draft(detail,0).get("html"));var c=command();long id=service.queue(detail,c);assertEquals(id,service.queue(detail,c));assertEquals("SENT",service.dispatch(id).get("status"));assertEquals("SENT",service.dispatch(id).get("status"));verify(transport,times(1)).send(any(),any(),eq(LegacyMailRoutingRules.Kind.REPORT));var received=sink.received.get(8,TimeUnit.SECONDS);assertEquals("报告发送",received.getSubject());assertEquals("text/html",received.getContentType().split(";")[0]);assertTrue(received.getContent().toString().contains("修订后的发送正文"));
  assertEquals(1,((Number)store.one("SELECT IsSendMail FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",detail).get("IsSendMail")).intValue());assertEquals(3,((Number)store.one("SELECT SampleStatus FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",order).get("SampleStatus")).intValue());assertEquals(original,store.one("SELECT MailReport,ReportResult FROM lin_lb_diagnosisdetail_info WHERE diagnosisdetail_id=?",detail));assertEquals(before,store.one("SELECT TestPrice,OrginalPrice,OrginalDiscount,PDFHttpUrl FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",detail));
 }
 @Test void manualAcceptedReportRecoversOriginalFlagsWithoutRepeatingSmtp(){
  long id=service.queue(detail,command());doThrow(new LegacyMailTransport.DeliveryUncertainException()).when(transport).send(any(),any(),any());assertEquals("UNKNOWN",service.dispatch(id).get("status"));assertEquals(0,((Number)store.one("SELECT IsSendMail FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",detail).get("IsSendMail")).intValue());
  var c=new LegacyReportMailService.ReconcileCommand("ACCEPTED","Synthetic report SMTP receipt confirms acceptance",true,false,service.message(id).get("editToken").toString(),key());assertEquals("SENT",service.reconcile(id,c).get("status"));assertEquals("SENT",service.reconcile(id,c).get("status"));verify(transport,times(1)).send(any(),any(),any());assertEquals(3,((Number)store.one("SELECT SampleStatus FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",order).get("SampleStatus")).intValue());
 }
 @Test void originalReportSendCanRetainEmptySubjectAndBody()throws Exception{var c=command();long id=service.queue(detail,new LegacyReportMailService.Command(contact,"","",key(),c.expectedToken(),"existing.pdf"));assertEquals("SENT",service.dispatch(id).get("status"));assertEquals("",sink.received.get(8,TimeUnit.SECONDS).getContent().toString());}
 @Test void explicitMailTemplateUsesOriginalReplacementWithoutSavingDraftToDetail(){
  long binding=store.insert("INSERT INTO lin_lb_dictbindkey(BindTable,ColumnName,DescName) VALUES('ListDiagnosisProject','AnimalName',?)",prefix);
  long template=store.insert("INSERT INTO lin_lb_dictmaildiagnosisreport(model_type,model_content,createtime,updatetime) VALUES(?,?,123,123)",prefix,"<p>{"+prefix+"}</p>");
  try{gate("legacy-order-details","{\"enabled\":false}");String html=service.draft(detail,template).get("html").toString();assertTrue(html.startsWith("<p>"+prefix+"</p>"));assertTrue(html.contains("Project/View/Detail.aspx?CID="));assertEquals("<p>原邮件正文</p>",store.one("SELECT MailReport FROM lin_lb_diagnosisdetail_info WHERE diagnosisdetail_id=?",detail).get("MailReport"));}
  finally{store.jdbc().update("DELETE FROM lin_lb_dictmaildiagnosisreport WHERE id=? AND model_type=?",template,prefix);store.jdbc().update("DELETE FROM lin_lb_dictbindkey WHERE id=? AND DescName=?",binding,prefix);}
 }
 @Test void missingOrReplacedPdfBlocksSendingBeforeSmtp()throws Exception{Files.delete(pdf);assertEquals(409,assertThrows(BusinessException.class,()->service.queue(detail,command())).getCode());try(var d=new PDDocument()){d.addPage(new PDPage());d.save(pdf.toFile());}long id=service.queue(detail,command());Files.writeString(pdf,"%PDF-changed");assertEquals("BLOCKED",service.dispatch(id).get("status"));verify(transport,never()).send(any(),any(),any());}
 @Test void reportFilenameCannotEscapeOrFollowSymlinks()throws Exception{var c=command();assertEquals(400,assertThrows(BusinessException.class,()->service.queue(detail,new LegacyReportMailService.Command(contact,c.title(),c.html(),key(),c.expectedToken(),"../existing.pdf"))).getCode());Files.delete(pdf);Files.createSymbolicLink(pdf,root.resolve("outside.pdf"));assertEquals(409,assertThrows(BusinessException.class,()->service.queue(detail,command())).getCode());}
}
